import pandas as pd, numpy as np, re
lab_raw=pd.read_csv('/root/environment/data/ckd_lab_data.csv')

MISSING={'','nan','none','null','na','n/a'}

def parse_token(x):
    if pd.isna(x):
        return np.nan
    s=str(x).strip()
    if s.lower() in MISSING:
        return np.nan
    # handle scientific via float after normalizing commas
    if ',' in s and '.' in s:
        # assume comma thousand sep
        s=s.replace(',','')
    elif ',' in s:
        s=s.replace(',','.')
    try:
        return float(s)
    except Exception:
        return np.nan

lab=lab_raw.copy()
for c in lab.columns:
    if c=='patient_id':
        continue
    lab[c]=lab[c].map(parse_token)

print('rows',len(lab))

# summary per column
cols=[c for c in lab.columns if c!='patient_id']
summary=[]
for c in cols:
    v=lab[c]
    miss=v.isna().mean()
    if v.notna().sum()==0:
        summary.append((c,miss,np.nan,np.nan,np.nan,np.nan,np.nan))
        continue
    q=v.quantile([0.01,0.05,0.5,0.95,0.99]).to_list()
    summary.append((c,miss,v.min(),q[0],q[2],q[4],v.max()))

# sort by missingness then by max
summary.sort(key=lambda t:(-t[1],- (t[6] if not pd.isna(t[6]) else -1)))
print(f"{'col':35s} miss  min    p01    med    p99    max")
for c,miss,mn,p01,med,p99,mx in summary:
    print(f"{c:35s} {miss:4.2f} {mn:7.2f} {p01:7.2f} {med:7.2f} {p99:7.2f} {mx:7.2f}")
PY"}

