        return np.nan
    s=str(x).strip()
    if s.lower() in {'','nan','none','null'}:
        return np.nan
    if ',' in s and '.' in s:
        s=s.replace(',','')
    elif ',' in s:
        s=s.replace(',','.')
    try:
        return float(s)
    except:
        return np.nan

mg=raw['Magnesium'].map(parse)
