import pandas as pd, numpy as np
raw=pd.read_csv('/root/environment/data/ckd_lab_data.csv')

def parse(x):
    if pd.isna(x):
        return np.nan
    s=str(x).strip()
    if s.lower() in {'','nan','none','null'}:
        return np.nan
    if ',' in s and '.' in s:
        s=s.replace(',','')
